function MonthView({date,appointments,absences,select}:{date:Date;appointments:Appointment[];absences:Absence[];select:(a:Appointment)=>void}){const first=new Date(date.getFullYear(),date.getMonth(),1),offset=(first.getDay()+6)%7,start=new Date(first);start.setDate(first.getDate()-offset);return <div className="month-grid"><div className="weekdays">{["Lun","Mar","Mié","Jue","Vie","Sáb","Dom"].map(x=><b>{x}</b>)}</div>{Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const items=appointments.filter(a=>new Date(a.startsAt).toDateString()===d.toDateString());const offs=absences.filter(a=>new Date(a.startsAt)<=new Date(d.getFullYear(),d.getMonth(),d.getDate(),23,59)&&new Date(a.endsAt)>=startOfDay(d));return <div className={`month-day ${d.getMonth()!==date.getMonth()?"muted-day":""}`}><time>{d.getDate()}</time>{items.map(a=><AppointmentCard a={a} onClick={()=>select(a)}/>)}{offs.map(x=><div className="absence-chip" style={{background:x.color}}>{x.title}</div>)}</div>})}</div>}
