function Stock(){const[items,setItems]=useState<Product[]>([]),[search,setSearch]=useState(""),[editing,setEditing]=useState<Product|null|undefined>(undefined);const load=()=>api<Product[]>(`/products?search=${encodeURIComponent(search)}`).then(setItems);useEffect(()=>{load()},[search]);return <section className="page"><div className="toolbar"><div><h2 className="section-title">Productos y stock</h2><p>Consulta visualmente los artículos, existencias y precios.</p></div><div className="actions"><div className="search-box"><Search/><input placeholder="Buscar producto…" value={search} onChange={e=>setSearch(e.target.value)}/></div><button className="primary-button" onClick={()=>setEditing(null)}><Plus/>Nuevo artículo</button></div></div><div className="stock-grid">{items.map(p=><article key={p.id} className={`stock-card ${Number(p.quantity)<=Number(p.minimum)?"low":""}`}><div className="stock-card-image">{p.imageData?<img src={p.imageData} alt={p.name}/>:<div><Boxes/><span>Sin foto</span></div>}<span className="stock-badge">{Number(p.quantity)<=Number(p.minimum)?"Stock bajo":"Disponible"}</span></div><div className="stock-card-body"><small>{p.category||"Producto"}{p.brand?` · ${p.brand}`:""}</small><h3>{p.name}</h3><div className="stock-numbers"><div><span>Stock</span><b>{Number(p.quantity)} {p.unit.toLowerCase()}</b></div><div><span>Mínimo</span><b>{Number(p.minimum)}</b></div></div><div className="stock-prices"><span>Coste {euro(p.cost)}</span><strong>{euro(p.price)}</strong></div><button className="secondary-button" onClick={()=>setEditing(p)}>Modificar artículo</button></div></article>)}</div>{!items.length&&<div className="content-card empty-stock">No hay productos registrados.</div>}{editing!==undefined&&<ProductModal product={editing} onClose={()=>setEditing(undefined)} onSaved={()=>{setEditing(undefined);load()}}/>}</section>}
function ProductModal({product,onClose,onSaved}:{product:Product|null;onClose:()=>void;onSaved:()=>void}){const[form,setForm]=useState({imageData:product?.imageData||"",name:product?.name||"",brand:product?.brand||"",category:product?.category||"",supplier:product?.supplier||"",unit:(product?.unit||"UNIDAD")as ProductUnit,quantity:Number(product?.quantity||0),minimum:Number(product?.minimum||0),cost:Number(product?.cost||0),price:Number(product?.price||0),notes:product?.notes||"",active:product?.active??true}),[error,setError]=useState("");async function choose(e:React.ChangeEvent<HTMLInputElement>){const file=e.target.files?.[0];if(!file)return;try{setForm({...form,imageData:await readServiceImage(file)})}catch(err:any){setError(err.message)}finally{e.target.value=""}}async function save(e:FormEvent){e.preventDefault();try{setError("");await api(product?`/products/${product.id}`:"/products",{method:product?"PUT":"POST",body:JSON.stringify(form)});onSaved()}catch(err:any){setError(err.message)}}return <Modal title={product?"Modificar artículo":"Nuevo artículo"} onClose={onClose}><form className="form-grid product-form" onSubmit={save}><div className="product-photo-editor wide">{form.imageData?<img src={form.imageData} alt="Vista previa"/>:<div><Boxes/><span>Añade una foto del artículo</span></div>}<div><label className="secondary-button">Seleccionar foto<input type="file" accept="image/jpeg,image/png,image/webp" onChange={choose}/></label>{form.imageData&&<button type="button" className="danger-button" onClick={()=>setForm({...form,imageData:""})}>Quitar foto</button>}</div></div><Field label="Nombre"><input value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Field><Field label="Marca"><input value={form.brand} onChange={e=>setForm({...form,brand:e.target.value})}/></Field><Field label="Categoría"><input value={form.category} onChange={e=>setForm({...form,category:e.target.value})}/></Field><Field label="Proveedor"><input value={form.supplier} onChange={e=>setForm({...form,supplier:e.target.value})}/></Field><Field label="Unidad"><select value={form.unit} onChange={e=>setForm({...form,unit:e.target.value as ProductUnit})}><option value="UNIDAD">Unidad</option><option value="GRAMO">Gramo</option><option value="MILILITRO">Mililitro</option><option value="LITRO">Litro</option></select></Field><Field label="Cantidad"><input type="number" min="0" step="0.01" value={form.quantity} onChange={e=>setForm({...form,quantity:Number(e.target.value)})}/></Field><Field label="Stock mínimo"><input type="number" min="0" step="0.01" value={form.minimum} onChange={e=>setForm({...form,minimum:Number(e.target.value)})}/></Field><Field label="Coste"><input type="number" min="0" step="0.01" value={form.cost} onChange={e=>setForm({...form,cost:Number(e.target.value)})}/></Field><Field label="Precio de venta"><input type="number" min="0" step="0.01" value={form.price} onChange={e=>setForm({...form,price:Number(e.target.value)})}/></Field><Field label="Notas"><textarea value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></Field>{error&&<div className="error-box wide">{error}</div>}<ModalActions onClose={onClose}/></form></Modal>}

function Employees(){const[items,setItems]=useState<Employee[]>([]),[editing,setEditing]=useState<Employee|null|undefined>(undefined);const load=()=>api<Employee[]>("/employees").then(setItems);useEffect(()=>{load()},[]);return <section className="page"><div className="toolbar"><p>Profesionales del salón</p><button className="primary-button" onClick={()=>setEditing(null)}><Plus/>Nueva empleada</button></div><div className="employee-grid">{items.map(x=><article key={x.id} className="employee-card"><i style={{background:x.color}}>{x.name[0]}</i><h3>{x.name}</h3><small>{x.email||"Sin correo"}</small><small>{x.phone||"Sin teléfono"}</small><button className="secondary-button employee-edit-button" onClick={()=>setEditing(x)}>Modificar</button></article>)}</div>{editing!==undefined&&<EmployeeModal employee={editing} onClose={()=>setEditing(undefined)} onSaved={()=>{setEditing(undefined);load()}}/>}</section>}
function EmployeeModal({employee,onClose,onSaved}:{employee:Employee|null;onClose:()=>void;onSaved:()=>void}){const[form,setForm]=useState({name:employee?.name||"",phone:employee?.phone||"",email:employee?.email||"",color:employee?.color||"#B8A48A",active:employee?.active??true}),[errors,setErrors]=useState<any>({});async function save(e:FormEvent){e.preventDefault();try{await api(employee?`/employees/${employee.id}`:"/employees",{method:employee?"PUT":"POST",body:JSON.stringify(form)});onSaved()}catch(e:any){setErrors(e.fields||{form:e.message})}}return <Modal title={employee?"Modificar empleada":"Nueva empleada"} onClose={onClose}><form className="form-grid" onSubmit={save}>{["name","phone","email"].map(k=><Field key={k} label={({name:"Nombre",phone:"Teléfono",email:"Correo"}as any)[k]} error={errors[k]}><input type={k==="email"?"email":"text"} value={(form as any)[k]} onChange={e=>setForm({...form,[k]:e.target.value})}/></Field>)}<Field label="Color"><input type="color" value={form.color} onChange={e=>setForm({...form,color:e.target.value})}/></Field><Field label="Estado"><select value={form.active?"activo":"inactivo"} onChange={e=>setForm({...form,active:e.target.value==="activo"})}><option value="activo">Activa</option><option value="inactivo">Inactiva</option></select></Field>{errors.form&&<div className="error-box wide">{errors.form}</div>}<ModalActions onClose={onClose}/></form></Modal>}

function Toolbar({search,setSearch,add,label}:{search:string;setSearch:(x:string)=>void;add:()=>void;label:string}){return <div className="toolbar"><div className="search-box"><Search/><input placeholder="Buscar…" value={search} onChange={e=>setSearch(e.target.value)}/></div><button className="primary-button" onClick={add}><Plus/>{label}</button></div>}
function SearchSelect({value,onChange,options}:{value:string;onChange:(v:string)=>void;options:{value:string;label:string}[]}){const id=useId();const[selected,setSelected]=useState(options.find(x=>x.value===value)?.label||"");useEffect(()=>setSelected(options.find(x=>x.value===value)?.label||""),[value,options]);return <div className="search-select"><Search/><input list={id} value={selected} onChange={e=>{setSelected(e.target.value);const x=options.find(o=>o.label===e.target.value);if(x)onChange(x.value)}} placeholder="Escribe para buscar…"/><datalist id={id}>{options.map(o=><option key={o.value} value={o.label}/>)}</datalist></div>}
function SearchMulti({values,onChange,options}:{values:string[];onChange:(v:string[])=>void;options:{value:string;label:string}[]}){const[q,setQ]=useState("");return <div><div className="search-box"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar servicio…"/></div><div className="multi-options">{options.filter(o=>o.label.toLowerCase().includes(q.toLowerCase())).map(o=><label><input type="checkbox" checked={values.includes(o.value)} onChange={e=>onChange(e.target.checked?[...values,o.value]:values.filter(v=>v!==o.value))}/>{o.label}</label>)}</div></div>}
function Field({label,error,children}:{label:string;error?:string;children:React.ReactNode}){return <label className={`field ${error?"invalid":""}`}><span>{label}</span>{children}{error&&<small>{error}</small>}</label>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){return <div className="modal-overlay"><div className="modal"><header><h2>{title}</h2><button onClick={onClose}><X/></button></header>{children}</div></div>}
function Drawer({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){return <div className="drawer-overlay" onClick={onClose}><aside className="drawer" onClick={e=>e.stopPropagation()}><header><h2>{title}</h2><button onClick={onClose}><X/></button></header>{children}</aside></div>}
function ModalActions({onClose}:{onClose:()=>void}){return <div className="modal-actions wide"><button type="button" className="secondary-button" onClick={onClose}>Cancelar</button><button className="primary-button">Guardar</button></div>}
